import sys, html, re
sys.path.insert(0,'.'); from dictionary import T, RACI
E=html.escape
LAYER={"WHAT":"What: assets","HOW":"How: rules","WHO":"Who: people and requests","GENERATED":"Generated by the sync","EVIDENCE":"Evidence"}
# ---------- Markdown
md=["# Security metadata dictionary","",
"The register in `SQLDB_SecMeta` (schema `sec`) holds every access rule for OneLake. This dictionary defines each table and column, with a real example from the lab (datasteward, Procurement buyer, OU 102). Keep it next to `P3_metamodel.sql`; when a column changes, change both.","",
"## Who prepares the rules","","| Activity | Does the work | Accountable | Consulted | Informed |","|---|---|---|---|---|"]
md+=[f"| {a} | {r} | {ac} | {c or '—'} | {i} |" for a,r,ac,c,i in RACI]
md+=["","Rule of thumb: the **Data Steward** writes the rules, the **domain SME** says which columns are sensitive, the **Data Owner** approves, the **Security Admin** loads them with a dry run, and **Internal Audit** reviews the evidence.",""]
for lay in LAYER:
    md+=[f"## {LAYER[lay]}",""]
    for lyr,t,purpose,owner,cols in T:
        if lyr!=lay: continue
        md+=[f"### `{t}`","",f"{purpose} **Maintained by:** {owner}.","","| Column | Definition | Example |","|---|---|---|"]
        md+=[f"| `{c}` | {d} | `{x}` |" for c,d,x in cols]+[""]
md+=["## How the pieces combine","","`AccessRequest` (who + `RoleTemplate` + scope + dates) → the template's `ObjectRule`, `RowRule` and `ColumnRule` per `Item` → one `RoleBinding` per template + scope + item (for example `PrcBuyerOU102` on LH_PRC_Gold, filter `org_id = '102'`) → Entra group `grp-ol-PrcBuyerOU102` holding everyone with an Active request → `AuditLog` for every change. `sec.vw_UserAccessDetail` shows the whole chain for one person.",""]
open(sys.argv[1],'w').write("\n".join(md))
# ---------- HTML section
h=['<section id="dictionary" data-tab="data-model">','  <span class="eyebrow">3.4 · Security metadata dictionary</span>','  <h2>Every table and column, with who maintains it</h2>',
'  <p class="lede">The register is the product: if a rule is not in these tables, no engine applies it. Examples are real rows from the lab, following datasteward (Procurement buyer, OU 102).</p>',
'  <h3 id="dictionary-who-prepares-the-rules">Who prepares the rules</h3>','  <div class="tablewrap"><table><thead><tr><th>Activity</th><th>Does the work</th><th>Accountable</th><th>Consulted</th><th>Informed</th></tr></thead><tbody>']
h+=[f'    <tr><td>{E(a)}</td><td><b>{E(r)}</b></td><td>{E(ac)}</td><td>{E(c) or "—"}</td><td>{E(i)}</td></tr>' for a,r,ac,c,i in RACI]
h+=['  </tbody></table></div>','  <div class="note">The Data Steward writes the rules, the domain SME says which columns are sensitive, the Data Owner approves, the Security Admin loads them with a dry run, and Internal Audit reviews the evidence.</div>']
for lay in LAYER:
    slug="dictionary-"+re.sub(r'[^a-z0-9]+','-',LAYER[lay].lower()).strip('-')
    h.append(f'  <h3 id="{slug}">{E(LAYER[lay])}</h3>')
    for lyr,t,purpose,owner,cols in T:
        if lyr!=lay: continue
        h.append(f'  <details class="dict"><summary><code>{E(t)}</code> · {E(purpose)} <span class="muted">Maintained by: {E(owner)}</span></summary>')
        h.append('  <div class="tablewrap"><table><thead><tr><th>Column</th><th>Definition</th><th>Example</th></tr></thead><tbody>')
        h+=[f'    <tr><td><code>{E(c)}</code></td><td>{E(d)}</td><td><code>{E(x)}</code></td></tr>' for c,d,x in cols]
        h.append('  </tbody></table></div></details>')
h+=['  <p><b>How the pieces combine:</b> AccessRequest (who + RoleTemplate + scope + dates) → the template\'s ObjectRule, RowRule and ColumnRule per Item → one RoleBinding per template + scope + item (<code>PrcBuyerOU102</code> on LH_PRC_Gold, filter <code>org_id = \'102\'</code>) → Entra group <code>grp-ol-PrcBuyerOU102</code> → AuditLog. <code>sec.vw_UserAccessDetail</code> shows the whole chain for one person.</p>',
'</section>']
open(sys.argv[2],'w').write("\n".join(h))
